#[cfg(test)]
mod tests {
  use super::*;

  #[test]
  fn test_get_auth_method_with_token() {
    let result = get_auth_method(Some("test_token".to_string()), false);
    assert!(result.is_ok());
    match result.unwrap() {
      AuthMethod::Token(token) => assert_eq!(token, "test_token"),
      _ => panic!("Expected Token variant"),
    }
  }

  #[test]
  fn test_get_auth_method_dry_run() {
    let result = get_auth_method(None, true);
    assert!(result.is_ok());
    match result.unwrap() {
      AuthMethod::Interactive => (),
      _ => panic!("Expected Interactive variant in dry-run mode"),
    }
  }

  #[test]
  fn test_get_auth_method_no_token_no_env() {
    // Temporarily unset GITHUB_ACTIONS to ensure we get the error case
    let _guard = setup_test_env();

    let result = get_auth_method(None, false);
    assert!(result.is_err());
    assert!(result.unwrap_err().to_string().contains("No means to authenticate"));
  }

  #[test]
  fn test_get_auth_method_terminal_input() {
    // This test assumes stdin is a terminal, which is typically true in test environments
    // unless explicitly mocked otherwise
    let result = get_auth_method(None, false);
    // If stdin is a terminal, this should return Interactive
    if result.is_ok() {
      match result.unwrap() {
        AuthMethod::Interactive => (),
        _ => panic!("Expected Interactive variant when stdin is terminal"),
      }
    }
    // If stdin is not a terminal, it might error, which is also acceptable
  }

  #[test]
  fn test_is_gha() {
    // This test just verifies the function runs without panicking
    let result = is_gha();
    // Result depends on environment, but function should not panic
    assert!(result.is_bool());
  }

  // Helper to temporarily set/unset environment variables for testing
  struct EnvGuard {
    vars: Vec<(String, Option<String>)>,
  }

  impl EnvGuard {
    fn new() -> Self {
      EnvGuard { vars: Vec::new() }
    }

    fn set(&mut self, key: &str, value: Option<&str>) {
      let prev = std::env::var(key).ok();
      if let Some(val) = value {
        std::env::set_var(key, val);
      } else {
        std::env::remove_var(key);
      }
      self.vars.push((key.to_string(), prev));
    }
  }

  impl Drop for EnvGuard {
    fn drop(&mut self) {
      for (key, value) in self.vars.drain(..) {
        match value {
          Some(v) => std::env::set_var(key, v),
          None => std::env::remove_var(key),
        }
      }
    }
  }

  fn setup_test_env() -> EnvGuard {
    let mut guard = EnvGuard::new();
    guard.set("GITHUB_ACTIONS", None);
    guard.set("ACTIONS_ID_TOKEN_REQUEST_URL", None);
    guard.set("ACTIONS_ID_TOKEN_REQUEST_TOKEN", None);
    guard
  }
}
