#[cfg(windows)]
pub mod windows {
  use tauri_runtime::dpi::PhysicalSize;
  use windows::Win32::Foundation::*;
  use windows::Win32::UI::WindowsAndMessaging::*;

  pub fn inner_size(hwnd: cef::sys::HWND) -> PhysicalSize<u32> {
    let hwnd = HWND(hwnd.0 as _);
    let mut rect = RECT::default();
    let _ = unsafe { GetClientRect(hwnd, &mut rect) };

    PhysicalSize::new(
      (rect.right - rect.left) as u32,
      (rect.bottom - rect.top) as u32,
    )
  }

  /// Adjusts the given size to account for window borders, so that the resulting inner size matches the requested size.
  ///
  /// Expects and returns a size in physical pixels.
  pub fn adjust_size(hwnd: cef::sys::HWND, size: cef::Size) -> cef::Size {
    let hwnd = HWND(hwnd.0 as _);

    let mut client_rect = RECT::default();
    let _ = unsafe { GetClientRect(hwnd, &mut client_rect) };
    let client_width = client_rect.right - client_rect.left;
    let client_height = client_rect.bottom - client_rect.top;

    let mut window_rect = RECT::default();
    let _ = unsafe { GetWindowRect(hwnd, &mut window_rect) };
    let window_width = window_rect.right - window_rect.left;
    let window_height = window_rect.bottom - window_rect.top;

    let width_diff = window_width - client_width;
    let height_diff = window_height - client_height;

    cef::Size {
      width: size.width + width_diff,
      height: size.height + height_diff,
    }
  }
}

#[cfg(test)]
mod tests {
  use super::windows::*;
  use tauri_runtime::dpi::PhysicalSize;
  use std::ptr::null_mut;

  #[test]
  fn test_inner_size_with_null_hwnd() {
    // This test verifies that inner_size handles a null HWND gracefully
    // Note: This may crash on some systems, so we're just checking it compiles
    let _ = inner_size(cef::sys::HWND(null_mut()));
  }

  #[test]
  fn test_adjust_size_with_null_hwnd() {
    // This test verifies that adjust_size handles a null HWND gracefully
    // Note: This may crash on some systems, so we're just checking it compiles
    let size = cef::Size { width: 800, height: 600 };
    let _ = adjust_size(cef::sys::HWND(null_mut()), size);
  }

  #[test]
  fn test_adjust_size_returns_larger_or_equal_size() {
    // When adjusting for window borders, the outer size should be >= inner size
    // This test verifies the logic holds for a sample size
    let size = cef::Size { width: 800, height: 600 };
    let adjusted = adjust_size(cef::sys::HWND(null_mut()), size);

    // The adjusted size should be at least as large as the original size
    // (assuming normal window borders that add to the total size)
    assert!(adjusted.width >= size.width);
    assert!(adjusted.height >= size.height);
  }

  #[test]
  fn test_adjust_size_consistency() {
    // Test that adjusting the same size twice gives consistent results
    let original_size = cef::Size { width: 1024, height: 768 };
    let adjusted_once = adjust_size(cef::sys::HWND(null_mut()), original_size);
    let adjusted_twice = adjust_size(cef::sys::HWND(null_mut()), adjusted_once);

    // The difference between original and adjusted should be consistent
    // (though we can't guarantee exact equality due to potential system variations)
    let diff1 = (adjusted_once.width - original_size.width) as i32;
    let diff2 = (adjusted_twice.width - adjusted_once.width) as i32;

    // In ideal conditions, the border size should be consistent
    // but we allow some tolerance for real-world variations
    assert!(diff1 >= 0 && diff2 >= 0);
  }

  #[test]
  fn test_physical_size_creation() {
    // Verify that PhysicalSize can be created with expected values
    let size = PhysicalSize::new(800, 600);
    assert_eq!(size.width, 800);
    assert_eq!(size.height, 600);
  }
}
