#[cfg(test)]
mod tests {
    use super::*;
    use crate::asm_lang::{Label, Span};

    fn make_op(opcode: impl Into<Either<VirtualOp, OrganizationalOp>>) -> Op {
        Op {
            opcode: opcode.into(),
            comment: String::new(),
            owning_span: None,
        }
    }

    fn make_jump(label: &str, jump_type: JumpType) -> Op {
        Op {
            opcode: Either::Right(OrganizationalOp::Jump {
                to: Label::from(label),
                type_: jump_type,
            }),
            comment: String::new(),
            owning_span: None,
        }
    }

    fn make_label(label: &str) -> Op {
        Op {
            opcode: Either::Right(OrganizationalOp::Label(Label::from(label))),
            comment: String::new(),
            owning_span: None,
        }
    }

    fn make_move(dst: VirtualRegister, src: VirtualRegister) -> Op {
        make_op(VirtualOp::MOVE(dst, src))
    }

    fn make_use(reg: VirtualRegister) -> Op {
        make_op(VirtualOp::USE(reg))
    }

    #[test]
    fn test_remove_sequential_jumps_unconditional() {
        let mut ais = AbstractInstructionSet {
            ops: vec![
                make_jump("target", JumpType::Unconditional),
                make_label("target"),
                make_op(VirtualOp::NOOP),
            ],
        };

        ais = ais.remove_sequential_jumps();

        assert_eq!(ais.ops[0].opcode, Either::Left(VirtualOp::NOOP));
        assert_eq!(ais.ops[1].opcode, Either::Right(OrganizationalOp::Label(Label::from("target"))));
        assert_eq!(ais.ops[2].opcode, Either::Left(VirtualOp::NOOP));
    }

    #[test]
    fn test_remove_sequential_jumps_not_zero() {
        let mut ais = AbstractInstructionSet {
            ops: vec![
                make_jump("target", JumpType::NotZero(VirtualRegister::Virtual(0))),
                make_label("target"),
                make_op(VirtualOp::NOOP),
            ],
        };

        ais = ais.remove_sequential_jumps();

        assert_eq!(ais.ops[0].opcode, Either::Left(VirtualOp::NOOP));
    }

    #[test]
    fn test_remove_sequential_jumps_no_removal() {
        let mut ais = AbstractInstructionSet {
            ops: vec![
                make_jump("other", JumpType::Unconditional),
                make_label("target"),
                make_op(VirtualOp::NOOP),
            ],
        };

        let original_ops = ais.ops.clone();
        ais = ais.remove_sequential_jumps();

        assert_eq!(ais.ops, original_ops);
    }

    #[test]
    fn test_remove_redundant_moves_basic() {
        let mut ais = AbstractInstructionSet {
            ops: vec![
                make_move(VirtualRegister::Virtual(0), VirtualRegister::Virtual(1)),
                make_use(VirtualRegister::Virtual(1)),
            ],
        };

        ais = ais.remove_redundant_moves();

        // The move to v0 should be removed since v0 is never used
        assert_eq!(ais.ops[0].opcode, Either::Left(VirtualOp::NOOP));
        assert_eq!(ais.ops[1].opcode, Either::Left(VirtualOp::USE(VirtualRegister::Virtual(1))));
    }

    #[test]
    fn test_remove_redundant_moves_no_removal() {
        let mut ais = AbstractInstructionSet {
            ops: vec![
                make_move(VirtualRegister::Virtual(0), VirtualRegister::Virtual(1)),
                make_use(VirtualRegister::Virtual(0)),
            ],
        };

        let original_ops = ais.ops.clone();
        ais = ais.remove_redundant_moves();

        assert_eq!(ais.ops, original_ops);
    }

    #[test]
    fn test_remove_redundant_ops_basic() {
        let mut ais = AbstractInstructionSet {
            ops: vec![
                make_op(VirtualOp::NOOP),
                make_move(VirtualRegister::Virtual(0), VirtualRegister::Virtual(0)),
                make_use(VirtualRegister::Virtual(1)),
            ],
        };

        ais = ais.remove_redundant_ops();

        assert_eq!(ais.ops.len(), 1);
        assert_eq!(ais.ops[0].opcode, Either::Left(VirtualOp::USE(VirtualRegister::Virtual(1))));
    }

    #[test]
    fn test_remove_redundant_ops_move_same_register() {
        let mut ais = AbstractInstructionSet {
            ops: vec![
                make_move(VirtualRegister::Virtual(0), VirtualRegister::Virtual(0)),
                make_use(VirtualRegister::Virtual(1)),
            ],
        };

        ais = ais.remove_redundant_ops();

        assert_eq!(ais.ops.len(), 1);
        assert_eq!(ais.ops[0].opcode, Either::Left(VirtualOp::USE(VirtualRegister::Virtual(1))));
