        self.active_operations.fetch_add(1, Ordering::Relaxed);
        let output = self.thread_pool.install(op);
        self.active_operations.fetch_sub(1, Ordering::Relaxed);
        // While reseting the pool panic catcher we return an error if we catched one.
        if self.pool_catched_panic.swap(false, Ordering::SeqCst) {
            Err(PanicCatched)
        } else {
            Ok(output)
        }
    }

    pub fn current_num_threads(&self) -> usize {
        self.thread_pool.current_num_threads()
    }

    /// The number of active operations.
    pub fn active_operations(&self) -> usize {
        self.active_operations.load(Ordering::Relaxed)
    }
}

#[derive(Error, Debug)]
#[error("A panic occured. Read the logs to find more information about it")]
pub struct PanicCatched;

#[derive(Default)]
pub struct ThreadPoolNoAbortBuilder(ThreadPoolBuilder);

impl ThreadPoolNoAbortBuilder {
    pub fn new() -> ThreadPoolNoAbortBuilder {
        ThreadPoolNoAbortBuilder::default()
    }

    pub fn new_for_indexing() -> ThreadPoolNoAbortBuilder {
        ThreadPoolNoAbortBuilder::default().thread_name(|index| format!("indexing-thread:{index}"))
    }

    pub fn thread_name<F>(mut self, closure: F) -> Self
    where
        F: FnMut(usize) -> String + 'static,
    {
        self.0 = self.0.thread_name(closure);
        self
    }

    pub fn num_threads(mut self, num_threads: usize) -> ThreadPoolNoAbortBuilder {
        self.0 = self.0.num_threads(num_threads);
        self
    }

    pub fn build(mut self) -> Result<ThreadPoolNoAbort, rayon::ThreadPoolBuildError> {
        let pool_catched_panic = Arc::new(AtomicBool::new(false));
        self.0 = self.0.panic_handler({
            let catched_panic = pool_catched_panic.clone();
            move |_result| catched_panic.store(true, Ordering::SeqCst)
        });
        Ok(ThreadPoolNoAbort {
            thread_pool: self.0.build()?,
            active_operations: AtomicUsize::new(0),
            pool_catched_panic,
        })
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::panic::{catch_unwind, AssertUnwindSafe};

    #[test]
    fn test_successful_operation() {
        let builder = ThreadPoolNoAbortBuilder::new();
        let pool = builder.build().unwrap();

        let result = pool.install(|| 42);
        assert_eq!(result.unwrap(), 42);
        assert_eq!(pool.active_operations(), 0);
    }

    #[test]
    fn test_panic_catching() {
        let builder = ThreadPoolNoAbortBuilder::new();
        let pool = builder.build().unwrap();

        let result = pool.install(|| panic!("Test panic"));
        assert!(matches!(result, Err(PanicCatched)));
        assert_eq!(pool.active_operations(), 0);
    }

    #[test]
    fn test_active_operations_count() {
        let builder = ThreadPoolNoAbortBuilder::new();
        let pool = builder.build().unwrap();

        // Test that active_operations increments during operation
        let active_ops = Arc::new(AtomicUsize::new(0));
        let active_ops_clone = active_ops.clone();

        let result = pool.install(move || {
            active_ops_clone.store(pool.active_operations(), Ordering::SeqCst);
            1 + 1
        });

        assert_eq!(result.unwrap(), 2);
        // During the operation, active_operations should have been 1
        assert_eq!(active_ops.load(Ordering::SeqCst), 1);
        assert_eq!(pool.active_operations(), 0);
    }

    #[test]
    fn test_current_num_threads() {
        let builder = ThreadPoolNoAbortBuilder::new().num_threads(4);
        let pool = builder.build().unwrap();

        // The actual number of threads may vary, but should be > 0
        let num_threads = pool.current_num_threads();
        assert!(num_threads > 0);
    }

    #[test]
    fn test_multiple_operations() {
        let builder = ThreadPoolNoAbortBuilder::new();
        let pool = builder.build().unwrap();

        // Run multiple operations
        let results: Vec<_> = (0..5)
            .map(|i| pool.install(move || i * 2))
            .collect();

        for (i, result) in results.iter().enumerate() {
            assert_eq!(result.unwrap(), i * 2);
        }

        assert_eq!(pool.active_operations(), 0);
    }
}
