        assert_eq!(log.topics[0], MessageSent::signature());
        assert_eq!(log.topics[1], H256::from_low_u64_be(1));
        assert_eq!(log.topics[2], H256::from_low_u64_be(2));
        assert_eq!(log.topics[3], H256::from_low_u64_be(100));
        assert!(!log.data.is_empty());
