        let msg = log.to_msg();
        assert_eq!(msg.sender().as_ref(), owner.as_ref());
        assert_eq!(msg.nonce(), 1);
        assert_eq!(msg.amount(), 100);
        assert_eq!(msg.data(), &Bytes::from(vec![1, 2, 3, 4]));
    }

