    fn test_log_to_tx_conversion() {
        let event = MessageSent {
            sender: H160::from_low_u64_be(1),
            recipient: H160::from_low_u64_be(2),
            amount: U64::from(100),
            nonce: U64::from(1),
            data: vec![1, 2, 3, 4],
        };

        let log = event_to_log::<MessageSentFilter>(event.into(), &crate::abi::bridge::MESSAGESENT_ABI);

        // This should panic because MessageSent is a message, not a transaction
        let result = std::panic::catch_unwind(|| {
            log.to_tx()
        });

        assert!(result.is_err());
    }

