mod tests {
    use super::*;
    use fuel_abi_types::error_codes;
    use fuel_tx::bytes::Bytes;
    use fuel_tx::Log;

    // Helper to create a simple LogDecoder for tests
    struct MockLogDecoder;

    impl LogDecoder for MockLogDecoder {
        fn decode_last_log(&self, _receipts: &[Receipt]) -> Result<String> {
            Ok("mock require message".to_string())
        }

        fn decode_last_two_logs(&self, _receipts: &[Receipt]) -> Result<(String, String)> {
            Ok(("left_value".to_string(), "right_value".to_string()))
        }
    }

    #[test]
    fn test_tx_status_success_check() {
        let status = TxStatus::Success {
            receipts: vec![],
        };
        assert!(status.check(None).is_ok());
    }

    #[test]
    fn test_tx_status_submitted_check() {
        let status = TxStatus::Submitted;
        assert!(status.check(None).is_ok());
    }

    #[test]
    fn test_tx_status_squeezed_out_check() {
        let status = TxStatus::SqueezedOut {
            reason: "test reason".to_string(),
        };
        let result = status.check(None);
        assert!(matches!(result, Err(Error::Transaction(Reason::SqueezedOut(r))) if r == "test reason"));
    }

    #[test]
    fn test_tx_status_revert_with_failed_assert_signal() {
        let receipts = vec![];
        let status = TxStatus::Revert {
            receipts,
            reason: "some reason".to_string(),
            revert_id: error_codes::FAILED_ASSERT_SIGNAL,
        };
        let result = status.check(None);
        assert!(matches!(result, Err(Error::Transaction(Reason::Reverted { reason, .. })) if reason == "assertion failed"));
    }

    #[test]
    fn test_tx_status_revert_with_failed_assert_eq_signal_and_decoder() {
        let receipts = vec![];
        let status = TxStatus::Revert {
            receipts,
            reason: "some reason".to_string(),
            revert_id: error_codes::FAILED_ASSERT_EQ_SIGNAL,
        };
        let decoder = MockLogDecoder;
        let result = status.check(Some(&decoder));
        assert!(matches!(result, Err(Error::Transaction(Reason::Reverted { reason, .. })) if reason.contains("left: `\"left_value\"`") && reason.contains("right: `\"right_value\"`")));
    }

    #[test]
    fn test_tx_status_revert_with_failed_require_signal_and_decoder() {
        let receipts = vec![];
        let status = TxStatus::Revert {
            receipts,
            reason: "some reason".to_string(),
            revert_id: error_codes::FAILED_REQUIRE_SIGNAL,
        };
        let decoder = MockLogDecoder;
        let result = status.check(Some(&decoder));
        assert!(matches!(result, Err(Error::Transaction(Reason::Reverted { reason, .. })) if reason == "mock require message"));
    }

    #[test]
    fn test_tx_status_take_receipts_success() {
        let receipts = vec![Receipt::Log(Log::default())];
        let status = TxStatus::Success { receipts: receipts.clone() };
        assert_eq!(status.take_receipts(), receipts);
    }

    #[test]
    fn test_tx_status_take_receipts_revert() {
        let receipts = vec![Receipt::Log(Log::default())];
        let status = TxStatus::Revert {
            receipts: receipts.clone(),
            reason: "reason".to_string(),
            revert_id: 0,
        };
        assert_eq!(status.take_receipts(), receipts);
    }

    #[test]
    fn test_tx_status_take_receipts_submitted() {
        let status = TxStatus::Submitted;
        assert!(status.take_receipts().is_empty());
    }

    #[test]
    fn test_tx_status_take_receipts_squeezed_out() {
        let status = TxStatus::SqueezedOut {
            reason: "reason".to_string(),
        };
        assert!(status.take_receipts().is_empty());
    }

    #[cfg(feature = "std")]
    #[test]
    fn test_from_client_transaction_status_success() {
        let client_status = ClientTransactionStatus::Success {
            receipts: vec![],
            block_id: Default::default(),
            time: Default::default(),
        };
        let tx_status = TxStatus::from(client_status);
        assert!(matches!(tx_status, TxStatus::Success { .. }));
    }

    #[cfg(feature = "std")]
    #[test]
    fn test_from_client_transaction_status_failure() {
        let client_status = ClientTransactionStatus::Failure {
            reason: "test failure".to_string(),
            program_state: Some(ProgramState::Revert(42)),
            receipts: vec![],
            block_id: Default::default(),
            time: Default::default(),
        };
        let tx_status = TxStatus::from(client_status);
        assert!(matches!(tx_status, TxStatus::Revert { revert_id, .. } if revert_id == 42));
    }

    #[cfg(feature = "std")]
    #[test]
    fn test_from_client_transaction_status_squeezed_out() {
        let client_status = ClientTransactionStatus::SqueezedOut {
            reason: "squeezed".to_string(),
        };
        let tx_status = TxStatus::from(client_status);
        assert!(matches!(tx_status, TxStatus::SqueezedOut { reason } if reason == "squeezed"));
    }

    #[cfg(feature = "std")]
    #[test]
    fn test_from_transaction_execution_status_success() {
        let exec_status = TransactionExecutionStatus {
            id: Default::default(),
            result: TransactionExecutionResult::Success {
                receipts: vec![],
                gas_used: 0,
            },
        };
        let tx_status = TxStatus::from(exec_status);
        assert!(matches!(tx_status, TxStatus::Success { .. }));
    }

    #[cfg(feature = "std")]
    #[test]
    fn test_from_transaction_execution_status_failed() {
        let exec_status = TransactionExecutionStatus {
            id: Default::default(),
            result: TransactionExecutionResult::Failed {
                result: Some(ProgramState::Revert(100)),
                receipts: vec![],
                gas_used: 0,
            },
        };
        let tx_status = TxStatus::from(exec_status);
        assert!(matches!(tx_status, TxStatus::Revert { revert_id, .. } if revert_id == 100));
    }
